history.command:
set -euo pipefail; cd /workspace/buggy; 
  find . -maxdepth 3 -type f -name 'libflint*.a' | head -n 5; 
  find . -maxdepth 3 -type d -name include | head -n 5; 
  # Compile probe using flint-config if available; otherwise use guessed include/lib paths.
  cat > /tmp/probe_find_roots.c <<'C'
#include <stdio.h>
#include "flint/flint.h"
#include "acb.h"
#include "acb_poly.h"

int main(void)
{
    acb_poly_t f;
    acb_ptr roots;

    acb_t c;
    acb_init(&c);

    acb_poly_init(f);

    acb_poly_set_coeff_si(f, 0, 10);
    acb_poly_set_coeff_si(f, 1, -170);
    acb_poly_set_coeff_si(f, 2, 2890);
    acb_poly_set_coeff_si(f, 3, -49130);
    acb_poly_set_coeff_si(f, 4, 835210);

    acb_set_ui(c, 83521);
    acb_poly_scalar_div(f, f, c, 64);

    // roots array length 4 (as expected by the defect report)
    roots = flint_malloc(4 * sizeof(acb_struct));
    for (int i=0;i<4;i++) acb_init(roots + i);

    long r = acb_poly_find_roots(roots, f, NULL, 40, 64);
    printf("root_count=%ld\n", r);

    for (int i=0;i<4;i++) acb_clear(roots + i);
    flint_free(roots);
    acb_poly_clear(f);
    acb_clear(c);
    return 0;
}
C

  # Determine include and lib dirs.
  INC=$(find . -maxdepth 4 -type d -name include | head -n 1 || true)
  [ -z "$INC" ] && INC=./include
  LIBDIR=$(find . -maxdepth 5 -type d -name .libs | head -n 1 || true)
  [ -z "$LIBDIR" ] && LIBDIR=.
  # Pick any static libs present.
  FLINT_A=$(find . -maxdepth 5 -type f -name 'libflint*.a' | head -n 1)
  if [ -z "$FLINT_A" ]; then echo 'No libflint*.a found'; exit 1; fi

  # Compile (linker usually needs gmp/mpfr/ntl/arb dependencies; try to use flint's ldflags if available).
  # Prefer using flint-config if present.
  if [ -f ./libtool ]; then true; fi
  if [ -f ./configure ]; then true; fi

  # Use pkg-config if available.
  if command -v pkg-config >/dev/null 2>&1 && pkg-config --exists flint 2>/dev/null; then
     echo 'using pkg-config flint';
     gcc -O2 -g -I"$INC" /tmp/probe_find_roots.c -o /tmp/probe_find_roots $(pkg-config --cflags flint) $(pkg-config --libs flint);
  else
     # Fallback: link with detected static lib plus gmp/mpfr.
     gcc -O2 -g -I"$INC" /tmp/probe_find_roots.c -o /tmp/probe_find_roots "$FLINT_A" -L"$LIBDIR" -lgmp -lmpfr -lm -lgcov || gcc -O2 -g -I"$INC" /tmp/probe_find_roots.c -o /tmp/probe_find_roots "$FLINT_A" -lgmp -lmpfr -lntl -lm || exit 1;
  fi

  /tmp/probe_find_roots | tee /tmp/probe_output_buggy.txt
